export const title = "How to Choose a Portable Monitor Stand That Leaves Room for Cables";
export const metaTitle = "Portable Monitor Stands That Leave Cable Room";
export const metaDescription = "Check a portable monitor stand in its deployed state, including support depth, orientation, cable exits, controls, and packing.";
